package store

import (
	"context"
	"database/sql"
)

// OutcomeRow is a joined outcome for API responses.
type OutcomeRow struct {
	MarketID        string
	ID              string
	Label           string
	ExternalID      sql.NullString
	CurrentOdds     float64
	LiquidityDepth  float64
	LiquidityLevels sql.NullString
	LastUpdated     string
	CanonicalKey    sql.NullString
}

type MarketRow struct {
	ID         string
	EventID    string
	Platform   string
	ExternalID string
	Sport      string
	League     string
	HomeTeam   string
	AwayTeam   string
	StartTime  string
	Status     string
	BetType    string
	Line       sql.NullFloat64
	MainLine   int
}

func (s *Store) ListActiveMarketsFlat(ctx context.Context) ([]MarketRow, []OutcomeRow, error) {
	mrows, err := s.db.QueryContext(ctx, `
		SELECT m.id, m.event_id, m.platform, m.external_id, e.sport, e.league, e.home_team, e.away_team,
		       m.start_time, m.status, m.bet_type, m.line, m.main_line
		FROM markets m JOIN events e ON m.event_id = e.id
		WHERE m.status = 'active' AND e.status = 'active' ORDER BY m.start_time ASC`)
	if err != nil {
		return nil, nil, err
	}
	defer mrows.Close()
	markets := make([]MarketRow, 0)
	marketIDs := make(map[string]struct{})
	for mrows.Next() {
		var m MarketRow
		if err := mrows.Scan(&m.ID, &m.EventID, &m.Platform, &m.ExternalID, &m.Sport, &m.League, &m.HomeTeam, &m.AwayTeam,
			&m.StartTime, &m.Status, &m.BetType, &m.Line, &m.MainLine); err != nil {
			return nil, nil, err
		}
		markets = append(markets, m)
		marketIDs[m.ID] = struct{}{}
	}
	if err := mrows.Err(); err != nil {
		return nil, nil, err
	}
	if len(marketIDs) == 0 {
		if markets == nil {
			markets = make([]MarketRow, 0)
		}
		return markets, make([]OutcomeRow, 0), nil
	}
	ids := make([]string, 0, len(marketIDs))
	for id := range marketIDs {
		ids = append(ids, id)
	}
	// simple IN query - sqlite limit - batch if needed
	orows, err := s.db.QueryContext(ctx, `
		SELECT o.id, o.market_id, o.label, o.external_id, o.current_odds, o.liquidity_depth, o.liquidity_levels, o.last_updated, c.key AS canonical_key
		FROM outcomes o
		LEFT JOIN canonical_bets c ON o.canonical_bet_id = c.id
		WHERE o.market_id IN (`+placeholders(len(ids))+`)`, argsStrings(ids)...)
	if err != nil {
		return nil, nil, err
	}
	defer orows.Close()
	outcomes := make([]OutcomeRow, 0)
	for orows.Next() {
		var o OutcomeRow
		if err := orows.Scan(&o.ID, &o.MarketID, &o.Label, &o.ExternalID, &o.CurrentOdds, &o.LiquidityDepth,
			&o.LiquidityLevels, &o.LastUpdated, &o.CanonicalKey); err != nil {
			return nil, nil, err
		}
		outcomes = append(outcomes, o)
	}
	return markets, outcomes, orows.Err()
}

func placeholders(n int) string {
	if n == 0 {
		return ""
	}
	b := make([]byte, 0, n*2)
	for i := 0; i < n; i++ {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, '?')
	}
	return string(b)
}

func argsStrings(ids []string) []any {
	a := make([]any, len(ids))
	for i := range ids {
		a[i] = ids[i]
	}
	return a
}

func (s *Store) GetOutcomeWithMarket(ctx context.Context, outcomeID string) (outcomeIDRet, marketID, label, extID, home, away string, err error) {
	row := s.db.QueryRowContext(ctx, `
		SELECT o.id, o.market_id, o.label, COALESCE(o.external_id,''), e.home_team, e.away_team
		FROM outcomes o JOIN markets m ON o.market_id = m.id JOIN events e ON m.event_id = e.id
		WHERE o.id = ?`, outcomeID)
	err = row.Scan(&outcomeIDRet, &marketID, &label, &extID, &home, &away)
	return
}

// Package sync implements Polymarket Gamma → SQLite market ingestion (moneyline "12" only).
//
// Data path (high level):
//  1. Read bot_config.eventClassificationTags (JSON array of slugs, e.g. ["nba","nhl"]).
//  2. Map each known slug to a Polymarket Gamma series_id (see leagues.go).
//  3. GET https://gamma-api.polymarket.com/events?active=true&closed=false&series_id=… (paginated).
//  4. Skip event titles that look like embedded "more markets" / spread / total rows.
//  5. quoteFromMoneyline12: pick the combined moneyline market (NBA/NHL/MLB), map title teams to
//     Gamma `outcomes` labels, attach CLOB token ids + prices (matches bot polymarket.ts).
//  6. store.UpsertPolyMarketQuote: event + market + canonical_bets + outcomes (canonicalize labels).
//  7. GET /api/markets reads active markets + outcomes from DB (marketsvc.BuildMarketsPayload).
//
// Common reasons for empty /api/markets: Gamma returned 0 events, quote step failed (title/ML/outcome map),
// upsert failed (DB), or outcomes skipped because labels did not canonicalize (see routercanon).
package sync

import (
	"context"
	"encoding/json"
	"log/slog"
	"strings"
	syncstd "sync"

	"github.com/easyspace-ai/polybet/internal/bookcache"
	"github.com/easyspace-ai/polybet/internal/config"
	"github.com/easyspace-ai/polybet/internal/store"
)

// Engine runs periodic Polymarket Gamma sync.
type Engine struct {
	cfg    *config.Config
	st     *store.Store
	cache  *bookcache.Cache
	logger *slog.Logger
	mu     syncstd.Mutex // avoid overlapping Once (matches Node marketSync running guard)
}

func NewEngine(cfg *config.Config, st *store.Store, cache *bookcache.Cache, logger *slog.Logger) *Engine {
	if logger == nil {
		logger = slog.Default()
	}
	return &Engine{cfg: cfg, st: st, cache: cache, logger: logger}
}

func parseTagListJSON(raw string) []string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil
	}
	var tags []string
	if err := json.Unmarshal([]byte(raw), &tags); err != nil {
		return nil
	}
	return tags
}

// Once fetches configured leagues and upserts Polymarket moneyline (12) games.
func (e *Engine) Once(ctx context.Context) error {
	if !e.mu.TryLock() {
		e.logger.Warn("market_sync_overlap_skip", "msg", "previous sync still running")
		return nil
	}
	defer e.mu.Unlock()

	raw, _, err := e.st.GetBotConfig(ctx, "eventClassificationTags")
	if err != nil {
		e.logger.Error("market_sync_config", "key", "eventClassificationTags", "err", err)
		return err
	}
	tags := parseTagListJSON(raw)
	leagues := leaguesFromTags(tags)
	e.logger.Info("market_sync_start",
		"tags_raw_len", len(strings.TrimSpace(raw)), "tags_parsed", tags, "leagues", len(leagues),
		"gamma_api", gammaAPI, "http_proxy_set", strings.TrimSpace(e.cfg.HTTPPlatformProxy) != "")

	totalEvents := 0
	upserted := 0
	skippedGameLines := 0
	skippedQuote := 0
	skippedUpsertErr := 0

	for _, lg := range leagues {
		e.logger.Info("market_sync_league_fetch", "league", lg.League, "series_id", lg.SeriesID, "sport", lg.Sport)
		events, err := fetchGammaEvents(ctx, e.cfg.HTTPPlatformProxy, lg.SeriesID)
		if err != nil {
			e.logger.Error("market_sync_gamma_http", "league", lg.League, "series_id", lg.SeriesID, "err", err)
			continue
		}
		totalEvents += len(events)
		e.logger.Info("market_sync_gamma_page", "league", lg.League, "events", len(events))

		for _, ev := range events {
			if stringsContainsGameLinesKeyword(ev.Title) {
				skippedGameLines++
				e.logger.Debug("market_sync_skip_submarket_title", "event_id", ev.ID, "title", ev.Title)
				continue
			}
			q, err := quoteFromMoneyline12(ev, lg)
			if err != nil {
				skippedQuote++
				e.logger.Debug("market_sync_skip_quote", "event_id", ev.ID, "title", ev.Title, "reason", err.Error())
				continue
			}
			for _, oc := range q.Outcomes {
				e.cache.SetFeeRate(oc.ExternalID, sportsFeeRate)
			}
			if err := e.st.UpsertPolyMarketQuote(ctx, q); err != nil {
				skippedUpsertErr++
				e.logger.Warn("market_sync_upsert_failed", "poly_event_id", ev.ID, "external_id", q.ExternalID, "err", err)
				continue
			}
			upserted++
			e.logger.Debug("market_sync_upsert_ok", "poly_event_id", ev.ID, "league", lg.League, "home", q.HomeTeam, "away", q.AwayTeam)
		}
		e.logger.Info("market_sync_league_done", "league", lg.League, "events_in_page", len(events))
	}

	// DB row counts for operators (best-effort)
	var nMkt, nOut int
	_ = e.st.DB().QueryRowContext(ctx, `SELECT COUNT(1) FROM markets WHERE status='active'`).Scan(&nMkt)
	_ = e.st.DB().QueryRowContext(ctx, `SELECT COUNT(1) FROM outcomes o JOIN markets m ON o.market_id=m.id WHERE m.status='active'`).Scan(&nOut)

	e.logger.Info("market_sync_done",
		"leagues", len(leagues), "gamma_events_total", totalEvents,
		"quotes_upserted", upserted, "skipped_quote", skippedQuote, "skipped_game_lines_title", skippedGameLines,
		"skipped_upsert_err", skippedUpsertErr,
		"db_active_markets", nMkt, "db_active_outcomes", nOut)
	return nil
}

func stringsContainsGameLinesKeyword(title string) bool {
	i := strings.Index(title, " - ")
	if i < 0 {
		return false
	}
	suf := strings.ToLower(title[i+3:])
	keywords := []string{"more markets", "goal", "total", "over", "under", "handicap", "spread"}
	for _, k := range keywords {
		if strings.Contains(suf, k) {
			return true
		}
	}
	return false
}

package sync

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

const gammaAPI = "https://gamma-api.polymarket.com"

type gammaMarket struct {
	ConditionID     string  `json:"conditionId"`
	Question        string  `json:"question"`
	ClobTokenIDs    string  `json:"clobTokenIds"`
	Outcomes        string  `json:"outcomes"`
	OutcomePrices   string  `json:"outcomePrices"`
	Active          bool    `json:"active"`
	Closed          bool    `json:"closed"`
	Liquidity       string  `json:"liquidity"`
	SportsMarketType *string `json:"sportsMarketType"`
	Line            *float64 `json:"line"`
	GameStartTime   *string `json:"gameStartTime"`
}

type gammaEvent struct {
	ID        string        `json:"id"`
	Slug      string        `json:"slug"`
	Title     string        `json:"title"`
	StartDate string        `json:"startDate"`
	EndDate   string        `json:"endDate"`
	Markets   []gammaMarket `json:"markets"`
}

func fetchGammaEvents(ctx context.Context, httpProxy string, seriesID int) ([]gammaEvent, error) {
	const maxRetries = 3
	var lastErr error

	for attempt := 0; attempt < maxRetries; attempt++ {
		if attempt > 0 {
			backoff := time.Duration(1<<uint(attempt-1)) * time.Second
			slog.Warn("gamma_http_retry", "attempt", attempt+1, "series_id", seriesID, "backoff", backoff.String())
			time.Sleep(backoff)
		}

		events, err := doFetchGammaEvents(ctx, httpProxy, seriesID)
		if err == nil {
			return events, nil
		}

		lastErr = err
		if !isRetryableError(err) {
			return nil, err
		}
		slog.Warn("gamma_http_retryable_error", "series_id", seriesID, "attempt", attempt+1, "err", err.Error())
	}

	return nil, lastErr
}

func isRetryableError(err error) bool {
	s := err.Error()
	return strings.Contains(s, "EOF") ||
		strings.Contains(s, "timeout") ||
		strings.Contains(s, "context deadline") ||
		strings.Contains(s, "connection reset") ||
		strings.Contains(s, "no such host") ||
		strings.Contains(s, "temporary failure")
}

func doFetchGammaEvents(ctx context.Context, httpProxy string, seriesID int) ([]gammaEvent, error) {
	var all []gammaEvent
	offset := 0
	const limit = 500
	tr := http.DefaultTransport
	if strings.TrimSpace(httpProxy) != "" {
		pu, err := url.Parse(httpProxy)
		if err != nil {
			return nil, err
		}
		tr = &http.Transport{Proxy: http.ProxyURL(pu)}
	}
	client := &http.Client{Transport: tr, Timeout: 60 * time.Second}
	for {
		q := url.Values{}
		q.Set("active", "true")
		q.Set("closed", "false")
		q.Set("limit", strconv.Itoa(limit))
		q.Set("offset", strconv.Itoa(offset))
		q.Set("series_id", strconv.Itoa(seriesID))
		u := gammaAPI + "/events?" + q.Encode()
		if offset == 0 {
			slog.Debug("gamma_http_request", "url", u)
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
		if err != nil {
			return nil, err
		}
		res, err := client.Do(req)
		if err != nil {
			return nil, err
		}
		body, err := io.ReadAll(res.Body)
		_ = res.Body.Close()
		if err != nil {
			return nil, err
		}
		if res.StatusCode != http.StatusOK {
			slog.Warn("gamma_http_non_200", "status", res.StatusCode, "series_id", seriesID, "offset", offset, "body_prefix", truncateForLog(string(body), 240))
			return nil, fmt.Errorf("gamma %d: %s", res.StatusCode, string(body))
		}
		var page []gammaEvent
		if err := json.Unmarshal(body, &page); err != nil {
			return nil, err
		}
		if len(page) == 0 {
			break
		}
		all = append(all, page...)
		if len(page) < limit {
			break
		}
		offset += limit
	}
	return all, nil
}

func truncateForLog(s string, max int) string {
	if len(s) <= max {
		return s
	}
	return s[:max] + "…"
}

func parseJSONStringArray(raw string) []string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil
	}
	var arr []string
	if err := json.Unmarshal([]byte(raw), &arr); err != nil {
		return nil
	}
	return arr
}

func parseJSONFloatArray(raw string) []float64 {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil
	}
	var arr []float64
	if err := json.Unmarshal([]byte(raw), &arr); err != nil {
		return nil
	}
	return arr
}

// parseJSONNumberArray unmarshals a JSON array of numbers or numeric strings (Gamma often uses strings).
func parseJSONNumberArray(raw string) []float64 {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil
	}
	var elems []json.RawMessage
	if err := json.Unmarshal([]byte(raw), &elems); err != nil {
		return nil
	}
	out := make([]float64, 0, len(elems))
	for _, el := range elems {
		var f float64
		if err := json.Unmarshal(el, &f); err == nil {
			out = append(out, f)
			continue
		}
		var s string
		if err := json.Unmarshal(el, &s); err == nil {
			if v, err := strconv.ParseFloat(strings.TrimSpace(s), 64); err == nil {
				out = append(out, v)
			}
		}
	}
	return out
}

func parseLiquidity(s string) float64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0
	}
	return f
}

package sync

import (
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/easyspace-ai/polybet/internal/domain"
)

const sportsFeeRate = 0.03

var shortTZOffsetRe = regexp.MustCompile(`([+-]\d{2})$`)

func applyFee(p, fee float64) float64 {
	if fee == 0 {
		return p
	}
	return p + fee*p*(1-p)
}

func parseGammaTime(raw string) (time.Time, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return time.Time{}, false
	}
	iso := strings.Replace(raw, " ", "T", 1)
	if shortTZOffsetRe.MatchString(iso) {
		iso = shortTZOffsetRe.ReplaceAllString(iso, "${1}:00")
	}
	layouts := []string{
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05.999999Z07:00",
	}
	for _, layout := range layouts {
		if t, err := time.Parse(layout, iso); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func startTimeFromEvent(ev gammaEvent) time.Time {
	for _, m := range ev.Markets {
		if m.GameStartTime != nil && strings.TrimSpace(*m.GameStartTime) != "" {
			if t, ok := parseGammaTime(*m.GameStartTime); ok {
				return t
			}
		}
	}
	if ev.EndDate != "" {
		if t, err := time.Parse(time.RFC3339, ev.EndDate); err == nil {
			return t
		}
	}
	if ev.StartDate != "" {
		if t, err := time.Parse(time.RFC3339, ev.StartDate); err == nil {
			return t
		}
	}
	return time.Now().UTC()
}

var titleStripRe = regexp.MustCompile(`(?i)^[^:]+:\s*`)
var titleSuffixRe = regexp.MustCompile(`\s+-\s+.+$`)

func extractTeams(title, ordering string) (home, away string, ok bool) {
	stripped := titleSuffixRe.ReplaceAllString(titleStripRe.ReplaceAllString(title, ""), "")
	re := regexp.MustCompile(`(?i)^(.+?)\s+vs\.?\s+(.+)$`)
	m := re.FindStringSubmatch(stripped)
	if m == nil {
		return "", "", false
	}
	first := strings.TrimSpace(m[1])
	second := strings.TrimSpace(m[2])
	if ordering == "home" {
		return first, second, true
	}
	return second, first, true
}

func isMoneyline(m *gammaMarket) bool {
	if m.SportsMarketType == nil {
		return true
	}
	return *m.SportsMarketType == "moneyline"
}

// findCombinedMoneylineMarket picks the single two-outcome moneyline Polymarket uses for NBA/NHL/MLB
// (one market, team names in `outcomes` JSON — not two separate "home wins?" binaries like soccer).
func findCombinedMoneylineMarket(markets []gammaMarket) *gammaMarket {
	var genericYesNo *gammaMarket
	for i := range markets {
		m := &markets[i]
		if !m.Active || m.Closed || !isMoneyline(m) {
			continue
		}
		labels := parseJSONStringArray(m.Outcomes)
		if len(labels) < 2 {
			continue
		}
		l0 := strings.ToLower(strings.TrimSpace(labels[0]))
		l1 := strings.ToLower(strings.TrimSpace(labels[1]))
		if (l0 == "yes" || l0 == "no") && (l1 == "yes" || l1 == "no") {
			if genericYesNo == nil {
				genericYesNo = m
			}
			continue
		}
		return m
	}
	return genericYesNo
}

// outcomeIndexForTitleTeam maps a title-derived team name to an index in Gamma's `outcomes` array.
func outcomeIndexForTitleTeam(titleTeam string, labels []string) int {
	t := strings.ToLower(strings.TrimSpace(titleTeam))
	if t == "" {
		return -1
	}
	for i, lb := range labels {
		l := strings.ToLower(strings.TrimSpace(lb))
		if l == "" || l == "yes" || l == "no" {
			continue
		}
		if l == t {
			return i
		}
	}
	best := -1
	for i, lb := range labels {
		l := strings.ToLower(strings.TrimSpace(lb))
		if l == "" || l == "yes" || l == "no" {
			continue
		}
		if strings.Contains(t, l) || strings.Contains(l, t) {
			if best < 0 {
				best = i
			}
		}
	}
	if best >= 0 {
		return best
	}
	parts := strings.Fields(t)
	if len(parts) > 0 {
		last := strings.ToLower(parts[len(parts)-1])
		for i, lb := range labels {
			l := strings.ToLower(strings.TrimSpace(lb))
			if l == "" {
				continue
			}
			if strings.Contains(l, last) || strings.Contains(last, l) {
				return i
			}
		}
	}
	return -1
}

func quoteFromMoneyline12(ev gammaEvent, lg League) (*domain.MarketQuote, error) {
	homeTitle, awayTitle, ok := extractTeams(ev.Title, lg.TitleOrdering)
	if !ok {
		return nil, fmt.Errorf("bad title")
	}
	ml := findCombinedMoneylineMarket(ev.Markets)
	if ml == nil {
		return nil, fmt.Errorf("missing moneyline")
	}
	outLabels := parseJSONStringArray(ml.Outcomes)
	tokens := parseJSONStringArray(ml.ClobTokenIDs)
	prices := parseJSONNumberArray(ml.OutcomePrices)
	if len(outLabels) < 2 || len(tokens) < 2 {
		return nil, fmt.Errorf("tokens")
	}
	hi := outcomeIndexForTitleTeam(homeTitle, outLabels)
	ai := outcomeIndexForTitleTeam(awayTitle, outLabels)
	if hi < 0 || ai < 0 || hi == ai {
		return nil, fmt.Errorf("outcome map")
	}
	homeLabel := strings.TrimSpace(outLabels[hi])
	awayLabel := strings.TrimSpace(outLabels[ai])
	tokenHome := tokens[hi]
	tokenAway := tokens[ai]
	if tokenHome == "" || tokenAway == "" {
		return nil, fmt.Errorf("tokens")
	}
	priceH := pickPrice(prices, hi, 0.5)
	priceA := pickPrice(prices, ai, 0.5)
	liq := parseLiquidity(ml.Liquidity)

	st := startTimeFromEvent(ev)
	// HomeTeam/AwayTeam must equal outcome labels so routercanon "12" canonicalization succeeds.
	name := homeLabel + " vs " + awayLabel
	return &domain.MarketQuote{
		Platform:    "polymarket",
		ExternalID:  ev.ID,
		Sport:       lg.Sport,
		League:      lg.League,
		HomeTeam:    homeLabel,
		AwayTeam:    awayLabel,
		Name:        name,
		StartTime:   st,
		BetType:     "12",
		MainLine:    true,
		PolyEventID: ev.ID,
		PolySlug:    strings.TrimSpace(ev.Slug),
		Outcomes: []domain.OutcomeOdds{
			{
				Label:       homeLabel,
				ImpliedOdds: applyFee(priceH, sportsFeeRate),
				ExternalID:  tokenHome,
				LiquidityDepth: domain.LiquidityDepth{
					AvailableSize: liq / 2,
				},
			},
			{
				Label:       awayLabel,
				ImpliedOdds: applyFee(priceA, sportsFeeRate),
				ExternalID:  tokenAway,
				LiquidityDepth: domain.LiquidityDepth{
					AvailableSize: liq / 2,
				},
			},
		},
	}, nil
}

func pickPrice(arr []float64, i int, def float64) float64 {
	if i < len(arr) {
		return arr[i]
	}
	return def
}

package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"github.com/easyspace-ai/polybet/internal/domain"
	"github.com/easyspace-ai/polybet/internal/routercanon"
)

// UpsertPolyMarketQuote inserts or updates event, market, canonical bets, and outcomes for one Polymarket quote.
func (s *Store) UpsertPolyMarketQuote(ctx context.Context, q *domain.MarketQuote) error {
	if q.Platform != "polymarket" {
		return fmt.Errorf("only polymarket quotes supported")
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	st := q.StartTime.UTC().Format(time.RFC3339Nano)
	var eventID string
	err = tx.QueryRowContext(ctx, `SELECT id FROM events WHERE poly_event_id = ? LIMIT 1`, q.PolyEventID).Scan(&eventID)
	if err == sql.ErrNoRows {
		eventID = "e_poly_" + q.PolyEventID
		_, err = tx.ExecContext(ctx, `
			INSERT INTO events(id, sport, league, home_team, away_team, start_time, status, poly_event_id, poly_slug)
			VALUES(?,?,?,?,?,?, 'active', ?, ?)`,
			eventID, q.Sport, q.League, q.HomeTeam, q.AwayTeam, st, q.PolyEventID, nullIfEmptyString(q.PolySlug))
		if err != nil {
			return err
		}
	} else if err != nil {
		return err
	} else {
		_, err = tx.ExecContext(ctx, `
			UPDATE events SET sport=?, league=?, home_team=?, away_team=?, start_time=?, status='active',
				poly_slug=COALESCE(NULLIF(TRIM(?), ''), poly_slug) WHERE id=?`,
			q.Sport, q.League, q.HomeTeam, q.AwayTeam, st, q.PolySlug, eventID)
		if err != nil {
			return err
		}
	}

	marketID := "m_poly_" + q.ExternalID
	lineVal := interface{}(nil)
	if q.Line != nil {
		lineVal = *q.Line
	}
	main := 0
	if q.MainLine {
		main = 1
	}
	_, err = tx.ExecContext(ctx, `
		INSERT INTO markets(id, event_id, platform, external_id, start_time, bet_type, line, main_line, status)
		VALUES(?,?,?,?,?,?,?,?, 'active')
		ON CONFLICT(platform, external_id) DO UPDATE SET
			event_id=excluded.event_id, start_time=excluded.start_time, bet_type=excluded.bet_type,
			line=excluded.line, main_line=excluded.main_line, status='active'`,
		marketID, eventID, "polymarket", q.ExternalID, st, q.BetType, lineVal, main)
	if err != nil {
		return err
	}

	for _, oc := range q.Outcomes {
		cr := routercanon.Canonicalize(oc.Label, q.BetType, q.HomeTeam, q.AwayTeam)
		if cr.Parts == nil {
			slog.Warn("outcome_canonicalize_skipped",
				"poly_event_id", q.PolyEventID, "market_external_id", q.ExternalID,
				"label", oc.Label, "bet_type", q.BetType, "home", q.HomeTeam, "away", q.AwayTeam,
				"reason", cr.Reason)
			continue
		}
		canonID := "cb_" + eventID + "_" + cr.Parts.Key
		_, err = tx.ExecContext(ctx, `
			INSERT INTO canonical_bets(id, event_id, key, bet_type, side, line)
			VALUES(?,?,?,?,?,?)
			ON CONFLICT(event_id, key) DO NOTHING`,
			canonID, eventID, cr.Parts.Key, cr.Parts.BetType, cr.Parts.Side, lineOrNil(cr.Parts.Line))
		if err != nil {
			return err
		}

		levelsJSON := ""
		if len(oc.LiquidityDepth.TopLevels) > 0 {
			b, _ := json.Marshal(oc.LiquidityDepth.TopLevels)
			levelsJSON = string(b)
		}
		outcomeID := "o_poly_" + oc.ExternalID
		_, err = tx.ExecContext(ctx, `
			INSERT INTO outcomes(id, market_id, label, external_id, current_odds, liquidity_depth, liquidity_levels, last_updated, canonical_bet_id)
			VALUES(?,?,?,?,?,?,?,datetime('now'), ?)
			ON CONFLICT(id) DO UPDATE SET
				label=excluded.label, current_odds=excluded.current_odds, liquidity_depth=excluded.liquidity_depth,
				liquidity_levels=excluded.liquidity_levels, last_updated=datetime('now'), canonical_bet_id=excluded.canonical_bet_id`,
			outcomeID, marketID, oc.Label, oc.ExternalID, oc.ImpliedOdds, oc.LiquidityDepth.AvailableSize, nullIfEmpty(levelsJSON), canonID)
		if err != nil {
			return err
		}
	}
	return tx.Commit()
}

func lineOrNil(l *float64) interface{} {
	if l == nil {
		return nil
	}
	return *l
}

func nullIfEmpty(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

func nullIfEmptyString(s string) interface{} {
	if strings.TrimSpace(s) == "" {
		return nil
	}
	return strings.TrimSpace(s)
}

